def solve(seq):
    """Run-length encode any iterable sequence (e.g., string, list, tuple).
    Returns a list of [element, count] for each consecutive run.
    Non‑iterable inputs yield an empty list.
    """
    # Try to get an iterator; if not possible, return empty list.
    try:
        it = iter(seq)
    except TypeError:
        return []
    # Attempt to get the first element.
    try:
        prev = next(it)
    except StopIteration:
        return []
    result = []
    count = 1
    for ch in it:
        if ch == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = ch
            count = 1
    result.append([prev, count])
    return result

