    """Return the determinant of a square integer matrix.
    Uses exact arithmetic with Fraction to avoid overflow or non‑integral intermediate steps.
    An empty matrix has determinant 1.
    """
    from fractions import Fraction
    n = len(matrix)
    if n == 0:
        return 1
    # Verify square
    for row in matrix:
        if len(row) != n:
            raise ValueError('Matrix must be square')
    # Make a copy as Fractions
    A = [[Fraction(val) for val in row] for row in matrix]
    det_sign = 1
    for i in range(n):
        # Find pivot
        pivot_row = None
        for r in range(i, n):
            if A[r][i] != 0:
                pivot_row = r
                break
        if pivot_row is None:
            return 0
        if pivot_row != i:
            A[i], A[pivot_row] = A[pivot_row], A[i]
            det_sign = -det_sign
        pivot = A[i][i]
        # Eliminate below
        for r in range(i+1, n):
            factor = A[r][i] / pivot
            for c in range(i, n):
                A[r][c] -= factor * A[i][c]
    # Determinant is product of diagonal entries times sign
    det = det_sign
    for i in range(n):
        det *= A[i][i]
    # det is Fraction but should be integer
    return int(det)
