    def det_bruteforce(m):
        n = len(m)
        if n == 0:
            return 1
        if n == 1:
            return m[0][0]
        total = 0
        for col in range(n):
            sub = [row[:col] + row[col+1:] for row in m[1:]]
            sign = -1 if col % 2 else 1
            total += sign * m[0][col] * det_bruteforce(sub)
        return total

    n = len(matrix)
    if n == 0:
        return 1
    # verify square – if not square treat as singular (det 0)
    for row in matrix:
        if len(row) != n:
            return 0
    # For very small matrices the recursive version is reliable and fast
    if n <= 5:
        return det_bruteforce(matrix)

    # Bareiss algorithm (fraction‑free elimination)
    A = [list(row) for row in matrix]  # copy
    sign = 1
    prev = 1  # previous pivot (A[k-1][k-1])
    for k in range(n-1):
        # pivot selection – if zero, try to swap with a lower row
        if A[k][k] == 0:
            swap = None
            for i in range(k+1, n):
                if A[i][k] != 0:
                    swap = i
                    break
            if swap is None:
                return 0  # singular matrix
            A[k], A[swap] = A[swap], A[k]
            sign = -sign
        pivot = A[k][k]
        # If previous pivot is zero (should only happen for singular matrices)
        if prev == 0:
            return 0
        for i in range(k+1, n):
            for j in range(k+1, n):
                # The division is exact for integer matrices
                A[i][j] = (A[i][j]*pivot - A[i][k]*A[k][j]) // prev
            A[i][k] = 0
