def solve(grid):
    """Count the number of islands in a binary grid.
    The grid may be empty, non-rectangular, or contain non‑list rows.
    Cells are connected orthogonally (up, down, left, right).
    """
    if not isinstance(grid, list) or not grid:
        return 0
    # Determine dimensions per row
    n = len(grid)
    # Use a set for visited coordinates
    visited = set()
    def is_land(i, j):
        if i < 0 or i >= n:
            return False
        row = grid[i]
        if not isinstance(row, list) or j < 0 or j >= len(row):
            return False
        return row[j] == 1
    def dfs(start_i, start_j):
        stack = [(start_i, start_j)]
        while stack:
            i, j = stack.pop()
            if (i, j) in visited:
                continue
            if not is_land(i, j):
                continue
            visited.add((i, j))
            stack.extend([(i-1, j), (i+1, j), (i, j-1), (i, j+1)])
    count = 0
    for i in range(n):
        row = grid[i]
        if not isinstance(row, list):
            continue
        for j in range(len(row)):
            if is_land(i, j) and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count
}

