def solve(matrix):
    """Return the determinant of a square integer matrix.
    An empty matrix has determinant 1.
    Uses exact arithmetic via Fraction to avoid floating errors.
    """
    if not matrix:
        return 1
    n = len(matrix)
    # Convert to Fraction for exact arithmetic
    from fractions import Fraction
    A = [[Fraction(x) for x in row] for row in matrix]
    det = Fraction(1)
    for i in range(n):
        # Find pivot row
        pivot = None
        for r in range(i, n):
            if A[r][i] != 0:
                pivot = r
                break
        if pivot is None:
            return 0
        if pivot != i:
            A[i], A[pivot] = A[pivot], A[i]
            det *= -1
        piv = A[i][i]
        det *= piv
        # Eliminate rows below
        for r in range(i + 1, n):
            factor = A[r][i] / piv
            for c in range(i, n):
                A[r][c] -= factor * A[i][c]
    # Determinant should be integer
    return int(det)

