def solve(matrix):
    """Return the determinant of an integer square matrix.
    Uses the Bareiss algorithm (fraction-free Gaussian elimination) which
    runs in O(n^3) and preserves integer arithmetic.
    An empty matrix has determinant 1.
    """
    if not matrix:
        return 1
    n = len(matrix)
    A = [row[:] for row in matrix]
    det = 1
    for k in range(n - 1):
        # Pivoting if needed
        if A[k][k] == 0:
            swap_row = None
            for i in range(k + 1, n):
                if A[i][k] != 0:
                    swap_row = i
                    break
            if swap_row is None:
                return 0
            A[k], A[swap_row] = A[swap_row], A[k]
            det = -det
        pivot = A[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                A[i][j] = (A[i][j] * pivot - A[i][k] * A[k][j]) // (A[k - 1][k - 1] if k > 0 else 1)
        for i in range(k + 1, n):
            A[i][k] = 0
    det *= A[n - 1][n - 1]
    return det

