def solve(grid):
    """Count islands in a possibly irregular binary grid.
    Cells are orthogonally connected. Non‑list rows or missing cells are treated as water.
    """
    if not isinstance(grid, list) or not grid:
        return 0
    n = len(grid)
    visited = set()
    def is_land(i, j):
        if i < 0 or i >= n:
            return False
        row = grid[i]
        if not isinstance(row, list):
            return False
        if j < 0 or j >= len(row):
            return False
        return row[j] == 1
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if (x, y) in visited:
                continue
            if not is_land(x, y):
                continue
            visited.add((x, y))
            stack.extend([(x-1, y), (x+1, y), (x, y-1), (x, y+1)])
    count = 0
    for i in range(n):
        row = grid[i]
        if not isinstance(row, list):
            continue
        for j in range(len(row)):
            if is_land(i, j) and (i, j) not in visited:
                dfs(i, j)
                count += 1
    return count

