    """Simplify a Unix‑style file path.
    The function works for both absolute and relative paths.
    It resolves '.' and '..' components, removes redundant slashes,
    and returns the canonical path.
    """
    # Determine if the path is absolute (starts with '/')
    is_abs = path.startswith('/')
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # Skip empty parts caused by // and current directory references
            continue
        if part == '..':
            if stack:
                stack.pop()
            else:
                # If relative path and stack empty, '..' stays (like ../../a)
                if not is_abs:
                    stack.append('..')
        else:
            stack.append(part)
    # Reconstruct the path
    if is_abs:
        return '/' + '/'.join(stack)
    else:
        return '/'.join(stack) if stack else '.'
