def solve(coins, amount):
    """Return the minimum number of coins needed to make up `amount` using unlimited
    coins from `coins`. If impossible, return -1.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Filter out non-positive coin values
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    # Initialize DP array where dp[i] = min coins for amount i
    INF = amount + 1  # any value larger than possible max
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i:
                if dp[i - c] + 1 < dp[i]:
                    dp[i] = dp[i - c] + 1
    return dp[amount] if dp[amount] != INF else -1

