    while i < n:
        ch = line[i]
        if in_quotes:
            if ch == '"':
                # Check for escaped double quote
                if i + 1 < n and line[i + 1] == '"':
                    field_chars.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field_chars.append(ch)
        else:
            if ch == ',':
                fields.append(''.join(field_chars))
                field_chars = []
            elif ch == '"':
                # Begin quoted field
                in_quotes = True
            else:
                field_chars.append(ch)
        i += 1
