def solve(weights, values, capacity):
    """Return the maximum total value achievable with given weights and values
    without exceeding the capacity. Each item can be used at most once.
    Uses 1‑dimensional DP for efficiency.
    """
    n = len(weights)
    if n == 0 or capacity <= 0:
        return 0
    # dp[w] = max value for total weight w
    dp = [0] * (capacity + 1)
    for i in range(n):
        w = weights[i]
        v = values[i]
        # iterate backwards to avoid reuse of same item
        for cur_w in range(capacity, w - 1, -1):
            new_val = dp[cur_w - w] + v
            if new_val > dp[cur_w]:
                dp[cur_w] = new_val
    return max(dp)

